function settings(){const s=S();s.plannerSettings ||= {};return s.plannerSettings}
const oldRestore=$('#restoreSectionsOpen'),dlg=$('#restoreSectionsDialog'),nav=$('nav');if(!oldRestore||!dlg||!nav)return;
oldRestore.remove();const gear=document.createElement('button');gear.id='plannerSettingsOpen';gear.type='button';gear.className='settings-gear';gear.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3.2"/><path d="M19.4 13.5a7.8 7.8 0 0 0 0-3l1.5-1.2-1.6-2.8-1.9.7a7.8 7.8 0 0 0-2.6-1.5L14.5 3h-3l-.4 2.7a7.8 7.8 0 0 0-2.6 1.5l-1.9-.7L5 9.3l1.5 1.2a7.8 7.8 0 0 0 0 3L5 14.7l1.6 2.8 1.9-.7a7.8 7.8 0 0 0 2.6 1.5l.4 2.7h3l.4-2.7a7.8 7.8 0 0 0 2.6-1.5l1.9.7 1.6-2.8z"/></svg>';gear.title='Planner settings';gear.setAttribute('aria-label','Open planner settings');nav.insertBefore(gear,$('#accountOpen'));
dlg.classList.add('settings-dialog');dlg.querySelector('.account-heading h2').textContent='Planner settings';dlg.querySelector(':scope > .hint')?.remove();dlg.querySelector(':scope > #removedSectionList')?.remove();const content=document.createElement('div');content.className='settings-content';content.innerHTML='<section><h3>Appearance</h3><h4>Choose a theme</h4><div id="themeStoryboards" class="theme-storyboards"></div><label>Language<select id="settingLanguage"></select></label></section><section><h3>Section titles</h3><p class="hint">Rename any section. Titles save with this planner.</p><div id="sectionTitleFields"></div></section><section><h3>Add a section</h3><p class="hint">Choose an optional section. You can remove and restore it later.</p><div id="sectionLibrary" class="section-library"></div></section><section><h3>Restore removed sections</h3><p class="hint">Removed sections keep their entries.</p><div id="removedSectionList"></div><div id="restoreCustomList"></div></section>';
dlg.append(content);gear.onclick=()=>{populateSettings();dlg.showModal()};
const languageSelect=$('#settingLanguage');languageNames.forEach(([id,name])=>{const o=document.createElement('option');o.value=id;o.textContent=name;languageSelect.append(o)});
const renameDialog=document.createElement('dialog');renameDialog.className='rename-section-dialog';renameDialog.innerHTML='<div class="account-heading"><h2>Rename section</h2><button type="button" aria-label="Close">×</button></div><form><label>Section title<input name="title" maxlength="60" required></label><div class="account-actions"><button type="button" data-cancel>Cancel</button><button type="submit">Save</button></div></form>';document.body.append(renameDialog);const renameForm=renameDialog.querySelector('form'),renameInput=renameForm.elements.title;let renameId='';function openTitleEditor(id,label){renameId=id;renameInput.value=S().sectionTitles?.[id]||label;renameDialog.showModal();renameInput.focus();renameInput.select()}renameDialog.querySelector('.account-heading button').onclick=()=>renameDialog.close();renameDialog.querySelector('[data-cancel]').onclick=()=>renameDialog.close();renameForm.onsubmit=e=>{e.preventDefault();S().sectionTitles ||= {};S().sectionTitles[renameId]=renameInput.value.trim();savePlanner();applyTitles();renameDialog.close()};
function dojoIcon(name){const paths={home:'<path d="m3 10 9-7 9 7M5 9v11h14V9M9 20v-7h6v7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',list:'<path d="M9 6h12M9 12h12M9 18h12"/><path d="M4 6h.01M4 12h.01M4 18h.01"/>',progress:'<path d="M4 20V10h4v10M10 20V4h4v16M16 20v-7h4v7"/><path d="M2 21h20"/>',journal:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h8M8 15h5"/>',care:'<path d="M12 21s-8-4.5-8-11a4.5 4.5 0 0 1 8-2.8A4.5 4.5 0 0 1 20 10c0 6.5-8 11-8 11z"/>',gear:'<circle cx="12" cy="12" r="3"/><path d="M19.4 13.5a7.8 7.8 0 0 0 0-3L21 9.3l-1.6-2.8-1.9.7a7.8 7.8 0 0 0-2.6-1.5L14.5 3h-3l-.4 2.7a7.8 7.8 0 0 0-2.6 1.5l-1.9-.7L5 9.3l1.5 1.2a7.8 7.8 0 0 0 0 3L5 14.7l1.6 2.8 1.9-.7a7.8 7.8 0 0 0 2.6 1.5l.4 2.7h3l.4-2.7a7.8 7.8 0 0 0 2.6-1.5l1.9.7 1.6-2.8z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',lotus:'<path d="M12 20c-5 0-8-3-8-7 3 0 6 2 8 7zm0 0c5 0 8-3 8-7-3 0-6 2-8 7zM12 20c-3-4-3-9 0-13 3 4 3 9 0 13zM4 16c-2-2-2-5-1-7 3 1 5 3 5 6m12 1c2-2 2-5 1-7-3 1-5 3-5 6"/>',menu:'<path d="M6 3v7M3.5 3v4M8.5 3v4M6 10v11M15 3v18M15 3c3 2 4 5 4 8h-4"/>',moon:'<path d="M20 15.5A8.5 8.5 0 0 1 8.5 4 8.5 8.5 0 1 0 20 15.5z"/>'};const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.innerHTML=paths[name]||paths.list;return svg}
function applyDojoNavigation(){const isDojo=settings().theme==='dojo';let rail=$('#dojoSidebar');if(!isDojo){rail?.remove();return}if(rail)return;const ids=[['Today','plannerTop','home'],['Planner','weekGlance','calendar'],['Habits','weeklyCare','list'],['Progress','dailyReview','progress'],['Journal','notesSection','journal'],['Wellbeing','careSection','care']];rail=document.createElement('aside');rail.id='dojoSidebar';rail.className='dojo-sidebar';rail.setAttribute('aria-label','Planner navigation');const list=document.createElement('div');list.className='dojo-nav-links';for(const [label,id,icon]of ids){const a=document.createElement('a');a.href='#'+id;a.append(dojoIcon(icon),document.createElement('span'));a.lastChild.textContent=label;if(id==='plannerTop')a.classList.add('active');a.onclick=()=>{rail.querySelectorAll('a').forEach(x=>x.classList.remove('active'));a.classList.add('active')};list.append(a)}const settingsLink=document.createElement('button');settingsLink.type='button';settingsLink.className='dojo-nav-settings';settingsLink.append(dojoIcon('gear'),document.createElement('span'));settingsLink.lastChild.textContent='Settings';settingsLink.onclick=()=>$('#plannerSettingsOpen')?.click();const motto=document.createElement('p');motto.className='dojo-calligraphy';motto.lang='ja';motto.textContent='継続は力なり';rail.append(list,settingsLink,motto);const header=$('header');if(header&&!header.id)header.id='plannerTop';$('.morning-section')?.setAttribute('id','morningSection');$('.care')?.setAttribute('id','careSection');$('.todo-section')?.setAttribute('id','todoSection');$('.menu')?.setAttribute('id','menuSection');$('.home')?.setAttribute('id','homeSection');$('.notes-section')?.setAttribute('id','notesSection');$('.weekly-section')?.setAttribute('id','weeklyCare');nav.after(rail)}
function applyDojoIcons(){const icons=[['.morning-section','sun'],['.care','lotus'],['.todo-section','list'],['.menu','menu'],['#weekGlance','calendar'],['#dailyReview','moon'],['.home','home'],['.notes-section','journal'],['.weekly-section','progress']];for(const [selector,name]of icons){const h=$(selector+' .section-head h2');if(!h)continue;let icon=h.querySelector('.dojo-section-icon');if(settings().theme==='dojo'){if(!icon){icon=dojoIcon(name);icon.classList.add('dojo-section-icon');h.prepend(icon)}}else icon?.remove()}}
function applyAppearance(){const p=settings(),theme=p.theme||'flower',palette=themePalettes[theme]||'blush';document.body.dataset.theme=theme;document.body.dataset.palette=palette;const vars=paletteVars[palette]||paletteVars.blush;Object.entries(vars).forEach(([name,value])=>document.body.style.setProperty(name,value));document.querySelector('meta[name="theme-color"]')?.setAttribute('content',vars['--page-bg']);applyDojoNavigation()}
function canonical(text,lang){const dict=dictionaries[lang]||{};if(dict[text])return dict[text];for(const [en,value]of Object.entries(dict))if(value===text)return en;return text}
function englishText(value){for(const dict of Object.values(dictionaries)){if(dict[value])return value;for(const [english,translated]of Object.entries(dict))if(translated===value)return english}return value}
function translateValue(value,dict){const original=String(value||''),base=englishText(original);if(dict[base])return dict[base];let m;if((m=base.match(/^Week of (.+) · Tap any day to update it\.$/)))return 'Semaine du '+m[1]+' · Touchez une journée pour la modifier.';if((m=base.match(/^(\d+) of 42 rituals this week · Most consistent: (.+) \((\d+)\/6\)\.$/)))return `${m[1]} rituels sur 42 cette semaine · Jour le plus régulier : ${m[2]} (${m[3]}/6).`;if((m=base.match(/^(\d+) of 30 days$/)))return `${m[1]} jours sur 30`;if((m=base.match(/^(.*) · (daily|weekly|weekdays)$/)))return `${m[1]} · ${{daily:'quotidienne',weekly:'hebdomadaire',weekdays:'en semaine'}[m[2]]}`;if((m=base.match(/^Complete to-do (\d+)$/)))return `Terminer la tâche ${m[1]}`;if((m=base.match(/^To-do (\d+)$/)))return `Tâche ${m[1]}`;if((m=base.match(/^Saved to cloud · (.+)$/)))return 'Enregistré dans le cloud · '+m[1];if((m=base.match(/^Saved on this device\. Cloud sync pending: (.+)$/)))return 'Enregistré sur cet appareil. Synchronisation en attente : '+m[1];if((m=base.match(/^Cloud unavailable; entries remain on this device\. (.+)$/)))return 'Cloud indisponible ; vos données restent sur cet appareil. '+m[1];if(base.startsWith('Delete ')&&base.endsWith(' completely'))return 'Supprimer « '+base.slice(7,-11)+' » définitivement';if(base.startsWith('Delete '))return 'Supprimer « '+base.slice(7)+' »';if(base.startsWith('Stop repeating '))return 'Arrêter de répéter « '+base.slice(15)+' »';if(base.startsWith('Move up '))return 'Déplacer « '+base.slice(8)+' » vers le haut';if(base.startsWith('Move down '))return 'Déplacer « '+base.slice(10)+' » vers le bas';if(base.startsWith('Restore '))return 'Restaurer '+(dict[base.slice(8)]||base.slice(8));if(base.startsWith('Edit ')&&base.endsWith(' routine'))return 'Modifier la '+(dict[base.slice(5,-8)]||base.slice(5,-8));if(base.startsWith('Edit '))return 'Modifier '+(dict[base.slice(5)]||base.slice(5));if(base.startsWith('Remove ')&&base.endsWith(' (you can restore it later)'))return 'Supprimer '+(dict[base.slice(7,-27)]||base.slice(7,-27))+' (restauration possible)';if(base.startsWith('Remove ')&&base.endsWith(' from planner'))return 'Supprimer '+(dict[base.slice(7,-13)]||base.slice(7,-13))+' de l’agenda';if(base.startsWith('Section title for '))return 'Titre de la section : '+base.slice(18);if(base.startsWith('Delete '))return 'Supprimer '+base.slice(7);return base}
function translatePage(){const lang=settings().language||'en';document.documentElement.lang=lang;document.body.dir=lang==='he'?'rtl':'ltr';const dict=dictionaries[lang]||{},walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);document.title=lang==='fr'?'Aujourd’hui est le jour — votre agenda quotidien':lang==='he'?'היום הוא היום — המתכנן היומי שלך':'Today Is The Day — your daily planner';let node;while(node){const parent=node.parentElement;if(parent?.closest('[data-user-custom-title]')){node=walker.nextNode();continue}const raw=node.nodeValue.trim(),translated=translateValue(raw,dict);if(raw!==translated){const left=node.nodeValue.match(/^\s*/)?.[0]||'',right=node.nodeValue.match(/\s*$/)?.[0]||'';node.nodeValue=left+translated+right}node=walker.nextNode()}for(const element of document.querySelectorAll('[placeholder],[aria-label],[title]'))for(const attr of ['placeholder','aria-label','title']){const value=element.getAttribute(attr);if(!value)continue;const translated=translateValue(value,dict);if(value!==translated)element.setAttribute(attr,translated)}}
if(!window.__plannerFrenchPrompts){window.__plannerFrenchPrompts=true;const nativeConfirm=window.confirm.bind(window),nativeAlert=window.alert.bind(window);window.confirm=message=>nativeConfirm(translateValue(message,dictionaries[settings().language]||{}));window.alert=message=>nativeAlert(translateValue(message,dictionaries[settings().language]||{}))}
function saveAndApply(){savePlanner();applyAppearance();translatePage();applyTitles()}
function setupTitleButtons(){for(const [id,selector,title]of titleSections){const section=$(selector),h=section?.querySelector('.section-head h2');if(!h||h.querySelector('.section-title-rename'))continue;let action=h.querySelector('button');if(action){const isAction=!!(action.id||action.onclick||action.getAttribute('onclick'));if(isAction&&['morningEdit','careEdit','homeEdit'].includes(action.id)){action.remove()}else if(isAction){const actionId=action.id;action.classList.add('section-title-action');action.textContent=actionId==='menuHistoryOpen'?'Plan week':section.classList.contains('notes-section')?'History':'Edit items';action.setAttribute('aria-label',action.textContent+' in '+title);action.title=action.textContent;section.querySelector('.section-head').append(action)}}const titleButton=document.createElement('button');titleButton.type='button';titleButton.className='section-title-rename';titleButton.onclick=e=>{e.preventDefault();e.stopPropagation();if(['morning','care','home'].includes(id)&&window.openPlannerItemEditor){window.openPlannerItemEditor(id);return}if(id==='menu'&&window.openWeeklyMenuEditor){window.openWeeklyMenuEditor();return}openTitleEditor(id,title)};titleButton.setAttribute('aria-label','Edit '+title);titleButton.textContent=(S().sectionTitles?.[id]||title)+' ♡';h.replaceChildren(titleButton);h.dataset.renameReady='true'}for(const item of S().extraSections||[]){const h=$(`#custom-section-${CSS.escape(item.id)} .section-head h2`);if(!h||h.querySelector('.section-title-rename'))continue;const b=document.createElement('button');b.type='button';b.className='section-title-rename';b.setAttribute('aria-label','Rename '+item.title);b.onclick=e=>{e.preventDefault();openTitleEditor('custom-'+item.id,item.title)};h.replaceChildren(b);h.dataset.renameReady='true'}}
function applyTitles(){setupTitleButtons();const saved=S().sectionTitles||{},mark=settings().theme==='dojo'?'':' ♡';for(const [id,selector,title]of titleSections){const el=$(selector),h=el?.querySelector('.section-head h2');if(!h)continue;let target=h.querySelector('.section-title-rename')||h.querySelector('button')||h;if(!target.dataset.defaultTitle)target.dataset.defaultTitle=(target.textContent||title).replace(/\s*♡\s*$/,'').trim()||title;const custom=saved[id]?.trim(),fallback=id==='dailyReview'?(new Date(($('#date').value||new Date().toISOString().slice(0,10))+'T12:00:00').getDay()===6?'Weekly Review':'Daily Review'):target.dataset.defaultTitle;target.textContent=(custom||fallback)+mark;if(custom)target.dataset.userCustomTitle='true';else delete target.dataset.userCustomTitle}for(const item of S().extraSections||[]){const h=$(`#custom-section-${CSS.escape(item.id)} .section-head h2`);if(!h)continue;const b=h.querySelector('.section-title-rename');if(b){b.textContent=(saved['custom-'+item.id]||item.title)+mark;b.dataset.userCustomTitle='true'}}applyDojoIcons()}
function renderThemeStoryboards(){const box=$('#themeStoryboards'),selected=settings().theme||'flower';box.replaceChildren();for(const [id,name]of themes){const card=document.createElement('button');card.type='button';card.className='theme-storyboard';card.dataset.theme=id;card.setAttribute('aria-pressed',String(selected===id));card.innerHTML=`<span class="theme-preview" data-theme="${id}" data-palette="${themePalettes[id]||'blush'}"><span class="theme-preview-top">♡</span><strong>${name}</strong><span class="theme-preview-subtitle">Small steps, steady progress</span><span class="theme-preview-section">Morning Routine</span><span class="theme-preview-lines"><i>□ Make Beds</i><i>□ A little intention</i></span></span><span class="theme-name">${name}</span>`;card.onclick=()=>{settings().theme=id;saveAndApply();populateSettings()};box.append(card)}}
function populateSettings(){const pref=settings();languageSelect.value=pref.language||'en';renderThemeStoryboards();renderTitles();renderLibrary();renderRestores();applyAppearance();translatePage()}
function renderTitles(){const box=$('#sectionTitleFields');box.replaceChildren();const all=[...titleSections,...(S().extraSections||[]).map(x=>['custom-'+x.id,`#custom-section-${CSS.escape(x.id)}`,x.title])];for(const [id,,name]of all){const label=document.createElement('label');label.className='section-title-field';label.textContent=name;const input=document.createElement('input');input.type='text';input.maxLength=60;input.placeholder=name;input.value=S().sectionTitles?.[id]||'';input.setAttribute('aria-label','Section title for '+name);input.oninput=()=>{S().sectionTitles ||= {};if(input.value.trim())S().sectionTitles[id]=input.value.trim();else delete S().sectionTitles[id];savePlanner();applyTitles()};label.append(input);box.append(label)}}
function dayState(){const s=S(),date=$('#date').value||new Date().toISOString().slice(0,10);return s.days[date] ||= {morning:{},care:{},home:{},todos:[],ink:{}}}
function renderExtras(){let root=$('#plannerCustomSections');if(!root)return;root.replaceChildren();for(const item of S().extraSections||[]){const section=document.createElement('section');section.className='custom-planner-section';section.id='custom-section-'+item.id;section.dataset.customSection=item.id;const head=document.createElement('div');head.className='section-head';const h=document.createElement('h2');h.textContent=(S().sectionTitles?.['custom-'+item.id]||item.title)+' ♡';h.dataset.userCustomTitle='true';head.append(h);const remove=document.createElement('button');remove.type='button';remove.className='remove-section-button';remove.textContent='×';remove.title='Remove '+item.title+' (you can restore it later)';remove.setAttribute('aria-label','Remove '+item.title+' from planner');remove.onclick=()=>{S().hiddenSections ||= {};S().hiddenSections['custom-'+item.id]=true;savePlanner();applyHidden();renderRestores()};head.append(remove);section.append(head);const body=document.createElement('div');const value=dayState().customSections?.[item.id]||{};if(item.kind==='check'){for(const [index,text]of item.items.entries()){const label=document.createElement('label');label.className='check-row';const check=document.createElement('input');check.type='checkbox';check.checked=!!value[index];check.onchange=()=>{const d=dayState();d.customSections ||= {};d.customSections[item.id] ||= {};d.customSections[item.id][index]=check.checked;savePlanner()};const span=document.createElement('span');span.textContent=text;label.append(check,span);body.append(label)}}else{const prompt=document.createElement('label');prompt.className='custom-section-prompt';prompt.textContent=item.prompt||'Write here…';const area=document.createElement('textarea');area.rows=3;area.value=value.text||'';area.placeholder=item.prompt||'Write here…';area.oninput=()=>{const d=dayState();d.customSections ||= {};d.customSections[item.id] ||= {};d.customSections[item.id].text=area.value;savePlanner()};prompt.append(area);body.append(prompt)}section.append(body);root.append(section)}applyHidden();applyTitles()}
function applyHidden(){const hidden=S().hiddenSections||{};for(const [id,selector]of staticSections)$(selector)?.classList.toggle('user-hidden-section',!!hidden[id]);for(const item of S().extraSections||[])$(`#custom-section-${CSS.escape(item.id)}`)?.classList.toggle('user-hidden-section',!!hidden['custom-'+item.id])}
function renderRestores(){const staticBox=$('#removedSectionList'),customBox=$('#restoreCustomList');staticBox.replaceChildren();customBox.replaceChildren();const hidden=S().hiddenSections||{};let n=0;for(const [id,,title]of staticSections){if(!hidden[id])continue;const b=document.createElement('button');b.type='button';b.className='restore-section-button';b.textContent='Restore '+title;b.onclick=()=>{delete S().hiddenSections[id];savePlanner();applyHidden();renderRestores()};staticBox.append(b);n++}for(const item of S().extraSections||[]){const id='custom-'+item.id;if(!hidden[id])continue;const b=document.createElement('button');b.type='button';b.className='restore-section-button';b.textContent='Restore '+(S().sectionTitles?.[id]||item.title);b.onclick=()=>{delete S().hiddenSections[id];savePlanner();applyHidden();renderRestores()};customBox.append(b);n++}if(!n)staticBox.textContent='No removed sections to restore.'}
function addTemplate(id){const source=templates.find(x=>x.id===id);if(!source)return;const item={...source,id:crypto.randomUUID(),items:source.items?[...source.items]:[]};S().extraSections ||= [];S().extraSections.push(item);savePlanner();renderExtras();renderTitles();renderLibrary()}
function renderLibrary(){const box=$('#sectionLibrary');box.replaceChildren();for(const template of templates){const card=document.createElement('div');card.className='section-template';const title=document.createElement('strong');title.textContent=template.title;const button=document.createElement('button');button.type='button';button.textContent='＋ Add';button.onclick=()=>addTemplate(template.id);card.append(title,button);box.append(card)}}
